"use client"

import type { ComponentProps } from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./empty.css"

const emptyVariants = cva("np-empty", {
  variants: {
    appearance: {
      default: "",
      outline: "np-empty-outline",
    },
  },
  defaultVariants: { appearance: "default" },
})

const emptyMediaVariants = cva("np-empty-media", {
  variants: {
    variant: {
      default: "",
      icon: "np-empty-media-icon",
    },
  },
  defaultVariants: { variant: "default" },
})

function Empty({
  className,
  appearance = "default",
  ...props
}: ComponentProps<"div"> & {
  appearance?: NonNullable<VariantProps<typeof emptyVariants>["appearance"]>
}) {
  return (
    <div
      data-slot="empty"
      data-appearance={appearance}
      className={cn(emptyVariants({ appearance }), className)}
      {...props}
    />
  )
}

function EmptyHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-header"
      className={cn("np-empty-header", className)}
      {...props}
    />
  )
}

function EmptyMedia({
  className,
  variant = "default",
  ...props
}: ComponentProps<"div"> & {
  variant?: NonNullable<VariantProps<typeof emptyMediaVariants>["variant"]>
}) {
  return (
    <div
      data-slot="empty-media"
      data-variant={variant}
      className={cn(emptyMediaVariants({ variant }), className)}
      {...props}
    />
  )
}

function EmptyTitle({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-title"
      className={cn("np-empty-title", className)}
      {...props}
    />
  )
}

function EmptyDescription({ className, ...props }: ComponentProps<"p">) {
  return (
    <p
      data-slot="empty-description"
      className={cn("np-empty-description", className)}
      {...props}
    />
  )
}

function EmptyContent({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-content"
      className={cn("np-empty-content", className)}
      {...props}
    />
  )
}

export {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
  emptyMediaVariants,
  emptyVariants,
}

/* nepui - Empty */

.np-empty,
[data-np-empty] {
  --np-spacing: 0.25rem;
  --np-empty-gap: calc(var(--np-spacing) * 4);
  --np-empty-padding: calc(var(--np-spacing) * 6);
  --np-empty-radius: var(--np-radius-xl);
  --np-empty-bg: transparent;
  --np-empty-border: var(--np-border);
  --np-empty-border-width: 0px;
  --np-empty-max-width: calc(var(--np-spacing) * 96);
  --np-empty-media-size: calc(var(--np-spacing) * 8);
  --np-empty-media-radius: var(--np-radius-lg);
  --np-empty-media-bg: var(--np-muted);
  --np-empty-media-color: var(--np-foreground);
  --np-empty-icon-size: calc(var(--np-spacing) * 4);

  box-sizing: border-box;
  display: flex;
  flex: 1 1 0%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--np-empty-gap);
  min-width: 0;
  padding: var(--np-empty-padding);
  border: var(--np-empty-border-width) dashed var(--np-empty-border);
  border-radius: var(--np-empty-radius);
  background: var(--np-empty-bg);
  text-align: center;
  text-wrap: balance;
}

:is(.np-empty, [data-np-empty]):is(
  .np-empty-outline,
  [data-appearance="outline"]
) {
  --np-empty-border-width: 1px;
}

.np-empty-header,
[data-np-empty-header] {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--np-spacing) * 2);
  max-width: var(--np-empty-max-width);
}

.np-empty-media,
[data-np-empty-media] {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  margin-block-end: calc(var(--np-spacing) * 2);
  background-color: transparent;
}

:is(.np-empty-media, [data-np-empty-media]) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(.np-empty-media, [data-np-empty-media]):is(
  .np-empty-media-icon,
  [data-variant="icon"]
) {
  width: var(--np-empty-media-size);
  height: var(--np-empty-media-size);
  border-radius: var(--np-empty-media-radius);
  background-color: var(--np-empty-media-bg);
  color: var(--np-empty-media-color);
}

:is(.np-empty-media, [data-np-empty-media]):is(
    .np-empty-media-icon,
    [data-variant="icon"]
  )
  svg:not([class*="size-"]) {
  width: var(--np-empty-icon-size);
  height: var(--np-empty-icon-size);
}

.np-empty-title,
[data-np-empty-title] {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: -0.025em;
  line-height: 1.25rem;
}

.np-empty-description,
[data-np-empty-description] {
  color: var(--np-muted-foreground);
  font-size: 0.875rem;
  line-height: 1.625;
}

:is(.np-empty-description, [data-np-empty-description]) > a {
  text-decoration: underline;
  text-underline-offset: 4px;
}

:is(.np-empty-description, [data-np-empty-description]) > a:hover {
  color: var(--np-primary);
}

.np-empty-content,
[data-np-empty-content] {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--np-spacing) * 2.5);
  width: 100%;
  min-width: 0;
  max-width: var(--np-empty-max-width);
  font-size: 0.875rem;
  text-wrap: balance;
}
